  ('saxon-switzerland-germany', '01F', 'Saxon Switzerland', 'Germany', 'Germany''s stone wilderness', 'live', 'verified', 'desertDunes', 'Saxony & the East', '{"adventure","culture","romance","family"}', '{}', '{"essential","comfort","premier","luxury"}', null, 'emerging', '{"key_facts":["Germany''s only rock national park, in the Elbe Sandstone Mountains (~700 km2, rock ~100 million years old)","The Bastei = pinnacles ~190 m above the Elbe + Bastei Bridge (wooden 1824, stone 1851) + ruined Neurathen rock castle","Koenigstein Fortress = one of Europe''s largest hilltop fortresses; 9.5-ha plateau 240 m above the Elbe, never conquered, ~600k visitors/yr (adult ~EUR 6)","Malerweg (Painters'' Way) ~116 km / 8 stages (opened 2006); follows Zingg + Graff (1766) and Caspar David Friedrich","Felsenbuehne Rathen ~1,800-seat rock stage, open-air since 1936; Saxon State Theatres May-Sep","Kirnitzschtalbahn narrow-gauge tram since 1898 (~8 km, Bad Schandau-Lichtenhain); Schrammsteine ridge + Lilienstein table mountain","Saxon climbing ~1,100 towers + ~17,000 routes; first ascent Falkenstein 1864; Saxon Climbing Rules (Fehrmann 1913): free climbing only, no metal, no chalk","Dresden = gateway (~45 min, own dossier); Czech side = Bohemian Switzerland cross-link; LOW-mountain sandstone, NOT alpine (no avalanche)"],"safety":{"emergency":"112 (fire + ambulance, EU) / 110 police; mountain/terrain rescue Bergwacht Sachsen via 112","hospital":"regional Sebnitz + Pirna; serious cases referred to Dresden (university/trauma centre)","advisory_level":"L2","advisory_codes":["T"],"malaria":"none","yellow_fever":"not required","activity_note":"LOW-mountain sandstone, NOT alpine (no glacier/avalanche); hazards = unguarded plateau/cliff edges, iron-rung ladder paths, slick-when-wet sandstone, sudden fog; free-climbing under the Saxon Climbing Rules (no metal/no chalk) - licensed/experienced only; winter = ice on ladder-paths","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/germany","read":"2026-08-19","page_updated":"2026-08-11T10:18:05+01:00"}},"timing":{"peak":"Jul-Aug (school holidays, full Felsenbuehne season) + autumn foliage late Sep-Oct","shoulder":"Apr-Jun, Sep-Oct (full trails, mild walking, thinner crowds; spring for climbing walls)","green":"Nov-Mar (misty + cheap; fortress + spa open, Felsenbuehne dark, tram/ferries reduced, icy ladder-paths)","booking_lead":"summer weekends + Felsenbuehne premieres + autumn foliage 2-3 mo (small bed stock); shoulder 2-4 wk; winter 1-2 wk","off_season_specials":"Nov-Mar spa + fortress + Romantic photography + Dresden-pairing breaks; Toskana Therme year-round anchor","event_peaks":"Felsenbuehne Rathen (May-Sep, verify premieres), school summer holidays (Jul-Aug), autumn foliage (Oct), Dresden Advent (Dec)","campaign_start":"AHEAD OF THE CURVE: fire spring/summer hiking + Malerweg + Felsenbuehne late Feb-Mar (1-2 wk before ~Apr season); fire autumn-foliage push in Aug; spa + fortress + Dresden-pairing year-round"},"jewels":[{"name":"The Bastei + Bastei Bridge circuit","si_tag":"Outdoor & Adventure","status":"future","tier":"essential","price_band":"free-~EUR 30/pp guided (approx; small Neurathen fee)","timing":"year-round; ~Apr-Oct best; early to beat crowds","draw_rank":1,"hook":"walk out among the pinnacles 190 m above the Elbe, cross the 1851 stone bridge and drop into the ruined Neurathen rock castle","si":"Outdoor & Adventure","blurb":"walk out among the pinnacles 190 m above the Elbe, cross the 1851 stone bridge and drop into the ruined Neurathen rock castle","when":"year-round; ~Apr-Oct best; early to beat crowds","commission":"DMC/guide wrapper"},{"name":"Schrammsteine ridge + ladder-path scramble","si_tag":"Outdoor & Adventure","status":"future","tier":"comfort","price_band":"~EUR 30-120/pp guided (approx)","timing":"dry rock ~Apr-Oct; avoid rain/ice","draw_rank":2,"hook":"a via-ferrata-style route up iron rungs to a jagged crest with plateau-edge views over the whole range — the most exhilarating day hike","si":"Outdoor & Adventure","blurb":"a via-ferrata-style route up iron rungs to a jagged crest with plateau-edge views over the whole range — the most exhilarating day hike","when":"dry rock ~Apr-Oct; avoid rain/ice","commission":"guide/operator 10-15%"},{"name":"Lilienstein table-mountain climb","si_tag":"Outdoor & Adventure","status":"future","tier":"essential","price_band":"free-~EUR 40/pp guided (approx)","timing":"snow/ice-free ~Apr-Oct","draw_rank":3,"si":"Outdoor & Adventure","when":"snow/ice-free ~Apr-Oct","commission":"guide wrapper"},{"name":"Guided Saxon-tower climbing","si_tag":"Outdoor & Adventure","status":"future","tier":"premier","price_band":"~EUR 90-250/pp/day (approx)","timing":"dry rock ~Apr-Oct; spring for south walls","draw_rank":4,"si":"Outdoor & Adventure","when":"dry rock ~Apr-Oct; spring for south walls","commission":"guide/operator 10-15%"},{"name":"Koenigstein Fortress","si_tag":"Culture & Heritage / History","status":"future","tier":"essential","price_band":"~EUR 6-15/pp (approx; guide adds)","timing":"year-round","draw_rank":1,"timing_type":"ALWAYS-ON","si":"Culture & Heritage / History","when":"year-round","commission":"DMC/guide (admission pass-through)"},{"name":"The Malerweg - walking into a Romantic painting","si_tag":"Culture & Heritage / History","status":"future","tier":"comfort","price_band":"~EUR 40-150/pp (approx; full package higher)","timing":"~Apr-Oct","draw_rank":2,"hook":"follow the \"Painters'' Way\" through the gorges and viewpoints Caspar David Friedrich turned into the icons of German Romanticism","si":"Culture & Heritage / History","blurb":"follow the \"Painters'' Way\" through the gorges and viewpoints Caspar David Friedrich turned into the icons of German Romanticism","when":"~Apr-Oct","commission":"DMC/operator 10-15%"},{"name":"Felsenbuehne Rathen - opera in the rocks","si_tag":"Culture & Heritage / History","status":"future","tier":"comfort","price_band":"~EUR 20-60/pp (app