insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('val-d-isere-france', '01F', 'Val d''Isère', 'France', 'Snow-sure to May at 1,850 metres', 'live', 'verified', 'northernLights', 'French Alps', '{"ski","adventure","ultra","romance","wellness","hiking"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Espace Killy / Tignes-Val d''Isere: 300 km pistes, ~80 lifts, 1,550-3,456 m, 154 runs (22 green/61 blue/46 red/25 black), vertical 1,906 m","Village at 1,850 m; snow-sure season late Nov to 3 May 2026; two glaciers (Grande Motte summer skiing + Pissaillas above 3,100 m)","Face de Bellevarde traced for the 1992 Albertville Olympics + 2009 World Championships (Killy/Bernhard Russi design)","Criterium de la Premiere Neige World Cup opener here since 1955 (2025: 12-14 Dec); men on Bellevarde, women on Oreiller-Killy","Resort of Jean-Claude Killy (triple 1968 Olympic champion); Espace Killy named for him; 10,000+ hectares lift-served off-piste","Three home sectors: Bellevarde (2,827 m), Solaise, Le Fornet (gateway to Pissaillas glacier)","Snow-front five-star cluster: Airelles (1,200 m2 Guerlain spa), Les Barmes de l''Ours (49 rms + 27 suites), Le K2 Chogori (opened Dec 2020), Le Refuge de Solaise (2,551 m)","La Folie Douce mid-mountain apres-ski; Vanoise National Park (535 km2, 1,700 plant species) for summer hiking; day pass ~EUR 75"],"safety":{"emergency":"112 (pan-European) / 15 SAMU / 17 police / 18 fire / 114 SMS-deaf / PGHM mountain rescue via 112","hospital":"Centre Hospitalier de Bourg-Saint-Maurice Tarentaise (~25 km; ER + trauma/orthopedic surgery + helipad); trauma transfer Chambery/Grenoble","advisory_level":"L2","malaria":"none","yellow_fever":"not required","activity_note":"High-alpine winter sports: off-piste avalanche risk (Meteo-France BRA + European 5-level scale; transceiver/shovel/probe + guide), altitude/AMS (top 3,456 m), glacier guided-only; mountain rescue PGHM via 112","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice